14	/// Expand the `#[elem]` macro.
15	pub fn elem(stream: TokenStream, body: syn::ItemStruct) -> Result<TokenStream> {
16	    let element = parse(stream, &body)?;
17	    create(&element)
18	}
19	
20	/// Details about an element.
21	struct Elem {
22	    /// The element's name as exposed to Typst.
23	    name: String,
24	    /// The element's title case name.
25	    title: String,
26	    /// The version of Typst the element was introduced in.
27	    since: Option<Since>,
28	    /// Whether this element has an associated scope defined by the `#[scope]` macro.
29	    scope: bool,
30	    /// A list of alternate search terms for this element.
31	    keywords: Vec<String>,
32	    /// The documentation for this element as a string.
33	    docs: String,
34	    /// The element's visibility.
35	    vis: syn::Visibility,
36	    /// The struct name for this element given in Rust.
37	    ident: Ident,
38	    /// The list of capabilities for this element.
39	    capabilities: Vec<Ident>,
40	    /// The fields of this element.
41	    fields: Vec<Field>,
42	}
43	
44	impl Elem {
45	    /// Whether the element has the given trait listed as a capability.
46	    fn can(&self, name: &str) -> bool {
47	        self.capabilities.iter().any(|capability| capability == name)
48	    }
49	
50	    /// Whether the element does not have the given trait listed as a
51	    /// capability.
52	    fn cannot(&self, name: &str) -> bool {
53	        !self.can(name)
54	    }
55	}
56	
57	impl Elem {
58	    /// All fields that are not just external.
59	    fn real_fields(&self) -> impl Iterator<Item = &Field> + Clone {
60	        self.fields.iter().filter(|field| !field.external)
61	    }
62	
63	    /// Fields that are present in the generated struct.
64	    fn struct_fields(&self) -> impl Iterator<Item = &Field> + Clone {
65	        self.real_fields().filter(|field| !field.ghost)
66	    }
67	
68	    /// Fields that get accessor, with, and push methods.
69	    fn accessor_fields(&self) -> impl Iterator<Item = &Field> + Clone {
70	        self.struct_fields().filter(|field| !field.required)
71	    }
72	
73	    /// Fields that are relevant for `Construct` impl.
74	    ///
75	    /// The reason why fields that are `parse` and internal are allowed is
76	    /// because it's a pattern used a lot for parsing data from the input and
77	    /// then storing it in a field.
78	    fn construct_fields(&self) -> impl Iterator<Item = &Field> + Clone {
79	        self.real_fields().filter(|field| {
80	            field.parse.is_some() || (!field.synthesized && !field.internal)
81	        })
82	    }
83	
84	    /// Fields that can be configured with set rules.
85	    fn set_fields(&self) -> impl Iterator<Item = &Field> + Clone {
86	        self.construct_fields().filter(|field| !field.required)
87	    }
88	}
89	
90	/// A field of an [element definition][`Elem`].
91	struct Field {
92	    /// The index of the field among all.
93	    i: u8,
94	    /// The name of this field.
95	    ident: Ident,
96	    /// The identifier `with_{ident}`.
97	    with_ident: Ident,
98	    /// The visibility of this field.
99	    vis: syn::Visibility,
100	    /// The type of this field.
101	    ty: syn::Type,
102	    /// The field's identifier as exposed to Typst.
103	    name: String,
104	    /// The documentation for this field as a string.
105	    docs: String,
106	    /// Whether this field is positional (as opposed to named).
107	    positional: bool,
108	    /// Whether this field is required.
109	    required: bool,
110	    /// Whether this field is variadic; that is, has its values
111	    /// taken from a variable number of arguments.
112	    variadic: bool,
113	    /// Whether this field has a `#[fold]` attribute.
114	    fold: bool,
115	    /// Whether this field is excluded from documentation.
116	    internal: bool,
117	    /// Whether this field exists only in documentation.
118	    external: bool,
119	    /// Whether this field has a `#[ghost]` attribute.
120	    ghost: bool,
121	    /// Whether this field has a `#[synthesized]` attribute.
122	    synthesized: bool,
123	    /// The contents of the `#[parse({..})]` attribute, if any.
124	    parse: Option<BlockWithReturn>,
125	    /// The contents of the `#[default(..)]` attribute, if any.
126	    default: Option<syn::Expr>,
127	}
128	
129	/// The `..` in `#[elem(..)]`.
130	struct Meta {
131	    scope: bool,
132	    name: Option<String>,
133	    title: Option<String>,
134	    since: Option<Since>,
135	    keywords: Vec<String>,
136	    capabilities: Vec<Ident>,
137	}
138	
139	impl Parse for Meta {
140	    fn parse(input: ParseStream) -> Result<Self> {
141	        Ok(Self {
142	            scope: parse_flag::<kw::scope>(input)?,
143	            name: parse_string::<kw::name>(input)?,
144	            title: parse_string::<kw::title>(input)?,
145	            since: parse_key_value::<kw::since, Since>(input)?,
146	            keywords: parse_string_array::<kw::keywords>(input)?,
147	            capabilities: Punctuated::<Ident, Token![,]>::parse_terminated(input)?
148	                .into_iter()
149	                .collect(),
150	        })
151	    }
152	}
153	
154	/// Parse details about the element from its struct definition.
155	fn parse(stream: TokenStream, body: &syn::ItemStruct) -> Result<Elem> {
156	    let meta: Meta = syn::parse2(stream)?;
157	    let (name, title) = determine_name_and_title(
158	        meta.name,
159	        meta.title,
160	        &body.ident,
161	        Some(|base| base.trim_end_matches("Elem")),
162	    )?;
163	
164	    let docs = documentation(&body.attrs)?;
165	
166	    let syn::Fields::Named(named) = &body.fields else {
167	        bail!(body, "expected named fields");
168	    };
169	
170	    let mut fields = named.named.iter().map(parse_field).collect::<Result<Vec<_>>>()?;
171	    fields.sort_by_key(|field| field.internal);
172	    for (i, field) in fields.iter_mut().enumerate() {
173	        field.i = i as u8;
174	    }
175	
176	    if fields.iter().any(|field| field.ghost && !field.internal)
177	        && meta.capabilities.iter().all(|capability| capability != "Construct")
178	    {
179	        bail!(
180	            body.ident,
181	            "cannot have public ghost fields and an auto-generated constructor",
182	        );
183	    }
184	
185	    Ok(Elem {
186	        name,
187	        title,
188	        since: meta.since,
189	        scope: meta.scope,
190	        keywords: meta.keywords,
191	        docs,
192	        vis: body.vis.clone(),
193	        ident: body.ident.clone(),
194	        capabilities: meta.capabilities,
195	        fields,
196	    })
197	}
198	
199	fn parse_field(field: &syn::Field) -> Result<Field> {
200	    let Some(ident) = field.ident.clone() else {
201	        bail!(field, "expected named field");
202	    };
203	
204	    if ident == "label" {
205	        bail!(ident, "invalid field name `label`");
206	    }
207	
208	    let mut attrs = field.attrs.clone();
209	    let variadic = has_attr(&mut attrs, "variadic");
210	    let required = has_attr(&mut attrs, "required") || variadic;
211	    let positional = has_attr(&mut attrs, "positional") || required;
212	
213	    let field = Field {
214	        i: 0,
215	        ident: ident.clone(),
216	        with_ident: format_ident!("with_{ident}"),
217	        vis: field.vis.clone(),
218	        ty: field.ty.clone(),
219	        name: ident.to_string().to_kebab_case(),
220	        docs: documentation(&attrs)?,
221	        positional,
222	        required,
223	        variadic,
224	        fold: has_attr(&mut attrs, "fold"),
225	        internal: has_attr(&mut attrs, "internal"),
226	        external: has_attr(&mut attrs, "external"),
227	        ghost: has_attr(&mut attrs, "ghost"),
228	        synthesized: has_attr(&mut attrs, "synthesized"),
229	        parse: parse_attr(&mut attrs, "parse")?.flatten(),
230	        default: parse_attr::<syn::Expr>(&mut attrs, "default")?.flatten(),
231	    };
232	
233	    if field.required && field.synthesized {
234	        bail!(ident, "required fields cannot be synthesized");
235	    }
236	
237	    if (field.required || field.synthesized)
238	        && (field.default.is_some() || field.fold || field.ghost)
239	    {
240	        bail!(ident, "required and synthesized fields cannot be default, fold, or ghost");
241	    }
242	
243	    validate_attrs(&attrs)?;
244	
245	    Ok(field)
246	}
247	
248	/// Produce the element's definition.
249	fn create(element: &Elem) -> Result<TokenStream> {
250	    // The struct itself.
251	    let struct_ = create_struct(element);
252	
253	    // Implementations.
254	    let inherent_impl = create_inherent_impl(element);
255	    let native_element_impl = create_native_elem_impl(element)?;
256	    let field_impls =
257	        element.fields.iter().map(|field| create_field_impl(element, field));
258	    let construct_impl =
259	        element.cannot("Construct").then(|| create_construct_impl(element));
260	    let set_impl = element.cannot("Set").then(|| create_set_impl(element));
261	    let mathy_impl = element.can("Mathy").then(|| create_mathy_impl(element));
262	
263	    // We use a const block to create an anonymous scope, as to not leak any
264	    // local definitions.
265	    Ok(quote! {
266	        #struct_
267	
268	        const _: () = {
269	            #inherent_impl
270	            #native_element_impl
271	            #(#field_impls)*
272	            #construct_impl
273	            #set_impl
274	            #mathy_impl
275	        };
276	    })
277	}
278	
279	/// Create the struct definition itself.
280	fn create_struct(element: &Elem) -> TokenStream {
281	    let Elem { vis, ident, docs, .. } = element;
282	
283	    let debug = element.cannot("Debug").then(|| quote! { Debug, });
284	    let fields = element.struct_fields().map(create_field);
285	    let oneliner = oneliner(docs);
286	
287	    quote! {
288	        #[doc = #oneliner]
289	        #[derive(Hash, #debug Clone)]
290	        #[expect(rustdoc::broken_intra_doc_links)]
291	        #vis struct #ident {
292	            #(#fields,)*
293	        }
294	    }
295	}
296	
297	/// Create a field declaration for the struct.
298	fn create_field(field: &Field) -> TokenStream {
299	    let Field { i, vis, ident, ty, .. } = field;
300	    if field.required {
301	        quote! { #vis #ident: #ty }
302	    } else if field.synthesized {
303	        quote! { #vis #ident: ::std::option::Option<#ty> }
304	    } else {
305	        quote! { #vis #ident: #foundations::Settable<Self, #i> }
306	    }
307	}
308	
309	/// Create the inherent implementation of the struct.
310	fn create_inherent_impl(element: &Elem) -> TokenStream {
311	    let Elem { ident, .. } = element;
312	
313	    let new_func = create_new_func(element);
314	    let with_field_methods = element.accessor_fields().map(create_with_field_method);
315	
316	    let style_consts = element.real_fields().map(|field| {
317	        let Field { i, vis, ident, .. } = field;
318	        quote! {
319	            #vis const #ident: #foundations::Field<Self, #i>
320	                = #foundations::Field::new();
321	        }
322	    });
323	
324	    quote! {
325	        impl #ident {
326	            #new_func
327	            #(#with_field_methods)*
328	        }
329	        #[expect(non_upper_case_globals)]
330	        impl #ident {
331	            #(#style_consts)*
332	        }
333	    }
334	}
335	
336	/// Create the `new` function for the element.
337	fn create_new_func(element: &Elem) -> TokenStream {
338	    let params = element
339	        .struct_fields()
340	        .filter(|field| field.required)
341	        .map(|Field { ident, ty, .. }| quote! { #ident: #ty });
342	
343	    let fields = element.struct_fields().map(|field| {
344	        let ident = &field.ident;
345	        if field.required {
346	            quote! { #ident }
347	        } else if field.synthesized {
348	            quote! { #ident: None }
349	        } else {
350	            quote! { #ident: #foundations::Settable::new() }
351	        }
352	    });
353	
354	    quote! {
355	        /// Create a new instance of the element.
356	        pub fn new(#(#params),*) -> Self {
357	            Self { #(#fields,)* }
358	        }
359	    }
360	}
361	
362	/// Create a builder-style setter method for a field.
363	fn create_with_field_method(field: &Field) -> TokenStream {
364	    let Field { vis, ident, with_ident, name, ty, .. } = field;
365	    let doc = format!("Builder-style setter for the [`{name}`](Self::{ident}) field.");
366	
367	    let expr = if field.required {
368	        quote! { self.#ident = #ident }
369	    } else if field.synthesized {
370	        quote! { self.#ident = Some(#ident) }
371	    } else {
372	        quote! { self.#ident.set(#ident) }
373	    };
374	
375	    quote! {
376	        #[doc = #doc]
377	        #vis fn #with_ident(mut self, #ident: #ty) -> Self {
378	            #expr;
379	            self
380	        }
381	    }
382	}
383	
384	/// Creates the element's `NativeElement` implementation.
385	fn create_native_elem_impl(element: &Elem) -> Result<TokenStream> {
386	    let Elem {
387	        name, ident, title, since, scope, keywords, docs, ..
388	    } = element;
389	    let def_site_key = ident.to_string();
390	
391	    let since = quote_option(since);
392	
393	    let fields = element.fields.iter().filter(|field| !field.internal).map(|field| {
394	        let i = field.i;
395	        if field.external {
396	            let positional = field.positional;
397	            let required = field.required;
398	            quote! { #foundations::ExternalFieldData::<#ident, #i>::vtable(#positional, #required) }
399	        } else if field.variadic {
400	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable_variadic() }
401	        } else if field.required {
402	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable() }
403	        } else if field.synthesized {
404	            quote! { #foundations::SynthesizedFieldData::<#ident, #i>::vtable() }
405	        } else if field.ghost {
406	            quote! { #foundations::SettablePropertyData::<#ident, #i>::vtable() }
407	        } else {
408	            quote! { #foundations::SettableFieldData::<#ident, #i>::vtable() }
409	        }
410	    });
411	
412	    let field_arms = element
413	        .fields
414	        .iter()
415	        .filter(|field| !field.internal && !field.external)
416	        .map(|field| {
417	            let Field { name, i, .. } = field;
418	            quote! { #name => Some(#i) }
419	        });
420	    let field_id = quote! {
421	        |name| match name {
422	            #(#field_arms,)*
423	            _ => None,
424	        }
425	    };
426	
427	    let capable_func = create_capable_func(element);
428	    let introspection = create_introspection_capabilities(element)?;
429	
430	    let with_keywords =
431	        (!keywords.is_empty()).then(|| quote! { .with_keywords(&[#(#keywords),*]) });
432	    let with_repr = element.can("Repr").then(|| quote! { .with_repr() });
433	    let with_partial_eq = element.can("PartialEq").then(|| quote! { .with_partial_eq() });
434	    let with_local_name = element.can("LocalName").then(|| quote! { .with_local_name() });
435	    let with_scope = scope.then(|| quote! { .with_scope() });
436	
437	    Ok(quote! {
438	        unsafe impl #foundations::NativeElement for #ident {
439	            const ELEM: #foundations::Element = #foundations::Element::from_vtable({
440	                static STORE: #foundations::LazyElementStore
441	                    = #foundations::LazyElementStore::new();
442	                static VTABLE: #foundations::ContentVtable =
443	                    #foundations::ContentVtable::new::<#ident>(
444	                        #name,
445	                        #title,
446	                        #since,
447	                        #docs,
448	                        ::typst_utils::DefSite { path: file!(), key: #def_site_key },
449	                        &[#(#fields),*],
450	                        #field_id,
451	                        #capable_func,
452	                        #introspection,
453	                        || &STORE,
454	                    ) #with_keywords
455	                    #with_repr
456	                    #with_partial_eq
457	                    #with_local_name
458	                    #with_scope
459	                    .erase();
460	                &VTABLE
461	            });
462	        }
463	    })
464	}
465	
466	/// Creates the appropriate trait implementation for a field.
467	fn create_field_impl(element: &Elem, field: &Field) -> TokenStream {
468	    let elem_ident = &element.ident;
469	    let Field { i, ty, ident, default, positional, name, docs, .. } = field;
470	    let def_site_key = format!("{elem_ident}::{ident}");
471	    let def_site = quote! {
472	        ::typst_utils::DefSite { path: file!(), key: #def_site_key }
473	    };
474	
475	    let default = match default {
476	        Some(default) => quote! { || #default },
477	        None => quote! { std::default::Default::default },
478	    };
479	
480	    if field.external {
481	        quote! {
482	            impl #foundations::ExternalField<#i> for #elem_ident {
483	                type Type = #ty;
484	                const FIELD: #foundations::ExternalFieldData<Self, #i> =
485	                    #foundations::ExternalFieldData::<Self, #i>::new(
486	                        #name,
487	                        #docs,
488	                        #def_site,
489	                        #default,
490	                    );
491	            }
492	        }
493	    } else if field.required {
494	        quote! {
495	            impl #foundations::RequiredField<#i> for #elem_ident {
496	                type Type = #ty;
497	                const FIELD: #foundations::RequiredFieldData<Self, #i> =
498	                    #foundations::RequiredFieldData::<Self, #i>::new(
499	                        #name,
500	                        #docs,
501	                        #def_site,
502	                        |elem| &elem.#ident,
503	                    );
504	            }
505	        }
506	    } else if field.synthesized {
507	        quote! {
508	            impl #foundations::SynthesizedField<#i> for #elem_ident {
509	                type Type = #ty;
510	                const FIELD: #foundations::SynthesizedFieldData<Self, #i> =
511	                    #foundations::SynthesizedFieldData::<Self, #i>::new(
512	                        #name,
513	                        #docs,
514	                        #def_site,
515	                        |elem| &elem.#ident,
516	                    );
517	            }
518	        }
519	    } else {
520	        let slot = quote! {
521	            || {
522	                static LOCK: ::std::sync::OnceLock<#ty> = ::std::sync::OnceLock::new();
523	                &LOCK
524	            }
525	        };
526	
527	        let with_fold = field.fold.then(|| quote! { .with_fold() });
528	        let refable = (!field.fold).then(|| {
529	            quote! {
530	                impl #foundations::RefableProperty<#i> for #elem_ident {}
531	            }
532	        });
533	
534	        if field.ghost {
535	            quote! {
536	                impl #foundations::SettableProperty<#i> for #elem_ident {
537	                    type Type = #ty;
538	                    const FIELD: #foundations::SettablePropertyData<Self, #i> =
539	                        #foundations::SettablePropertyData::<Self, #i>::new(
540	                            #name,
541	                            #docs,
542	                            #def_site,
543	                            #positional,
544	                            #default,
545	                            #slot,
546	                        ) #with_fold;
547	                }
548	                #refable
549	            }
550	        } else {
551	            quote! {
552	                impl #foundations::SettableField<#i> for #elem_ident {
553	                    type Type = #ty;
554	                    const FIELD: #foundations::SettableFieldData<Self, #i> =
555	                        #foundations::SettableFieldData::<Self, #i>::new(
556	                            #name,
557	                            #docs,
558	                            #def_site,
559	                            #positional,
560	                            |elem| &elem.#ident,
561	                            |elem| &mut elem.#ident,
562	                            #default,
563	                            #slot,
564	                        ) #with_fold;
565	                }
566	                #refable
567	            }
568	        }
569	    }
570	}
571	
572	/// Creates the element's `Construct` implementation.
573	fn create_construct_impl(element: &Elem) -> TokenStream {
574	    let ident = &element.ident;
575	    let setup = element.construct_fields().map(|field| {
576	        let (prefix, value) = create_field_parser(field);
577	        let ident = &field.ident;
578	        quote! {
579	            #prefix
580	            let #ident = #value;
581	        }
582	    });
583	
584	    let fields = element.struct_fields().map(|field| {
585	        let ident = &field.ident;
586	        if field.required {
587	            quote! { #ident }
588	        } else if field.synthesized {
589	            quote! { #ident: None }
590	        } else {
591	            quote! { #ident: #foundations::Settable::from(#ident) }
592	        }
593	    });
594	
595	    quote! {
596	        impl #foundations::Construct for #ident {
597	            fn construct(
598	                engine: &mut ::typst_library::engine::Engine,
599	                args: &mut #foundations::Args,
600	            ) -> ::typst_library::diag::SourceResult<#foundations::Content> {
601	                #(#setup)*
602	                Ok(#foundations::Content::new(Self { #(#fields),* }))
603	            }
604	        }
605	    }
606	}
607	
608	/// Creates the element's `Set` implementation.
609	fn create_set_impl(element: &Elem) -> TokenStream {
610	    let ident = &element.ident;
611	    let handlers = element.set_fields().map(|field| {
612	        let field_ident = &field.ident;
613	        let (prefix, value) = create_field_parser(field);
614	        quote! {
615	            #prefix
616	            if let Some(value) = #value {
617	                styles.set(Self::#field_ident, value);
618	            }
619	        }
620	    });
621	
622	    quote! {
623	        impl #foundations::Set for #ident {
624	            fn set(
625	                engine: &mut ::typst_library::engine::Engine,
626	                args: &mut #foundations::Args,
627	            ) -> ::typst_library::diag::SourceResult<#foundations::Styles> {
628	                let mut styles = #foundations::Styles::new();
629	                #(#handlers)*
630	                Ok(styles)
631	            }
632	        }
633	    }
634	}
635	
636	/// Create argument parsing code for a field.
637	fn create_field_parser(field: &Field) -> (TokenStream, TokenStream) {
638	    if let Some(BlockWithReturn { prefix, expr }) = &field.parse {
639	        return (quote! { #(#prefix);* }, quote! { #expr });
640	    }
641	
642	    let name = &field.name;
643	    let value = if field.variadic {
644	        quote! { args.all()? }
645	    } else if field.required {
646	        quote! { args.expect(#name)? }
647	    } else if field.positional {
648	        quote! { args.find()? }
649	    } else {
650	        quote! { args.named(#name)? }
651	    };
652	
653	    (quote! {}, value)
654	}
655	
656	/// Creates the element's casting vtable.
657	fn create_capable_func(element: &Elem) -> TokenStream {
658	    // Forbidden capabilities, i.e capabilities that are not object safe or
659	    // introspection capabilities that are handled otherwise.
660	    const FORBIDDEN: &[&str] = &[
661	        // Not object safe.
662	        "Debug",
663	        "PartialEq",
664	        "Hash",
665	        "Construct",
666	        "Set",
667	        "Repr",
668	        "LocalName",
669	        // Introspection capabilities.
670	        "Locatable",
671	        "Unqueriable",
672	        "Tagged",
673	    ];
674	
675	    let ident = &element.ident;
676	    let relevant = element
677	        .capabilities
678	        .iter()
679	        .filter(|&ident| !FORBIDDEN.contains(&(&ident.to_string() as &str)));
680	
681	    let checks = relevant.map(|capability| {
682	        quote! {
683	            if capability == ::std::any::TypeId::of::<dyn #capability>() {
684	                // Safety: The vtable function doesn't require initialized
685	                // data, so it's fine to use a dangling pointer.
686	                return Some(unsafe {
687	                    ::typst_utils::fat::vtable(dangling as *const dyn #capability)
688	                });
689	            }
690	        }
691	    });
692	
693	    quote! {
694	        |capability| {
695	            let dangling = ::std::ptr::NonNull::<#foundations::Packed<#ident>>::dangling().as_ptr();
696	            #(#checks)*
697	            None
698	        }
699	    }
700	}
701	
702	/// Creates the element's casting vtable.
703	fn create_introspection_capabilities(element: &Elem) -> Result<TokenStream> {
704	    let find_cap = |name| element.capabilities.iter().find(|ident| *ident == name);
705	    let locatable = find_cap("Locatable");
706	    let unqueriable = find_cap("Unqueriable");
707	    let tagged = find_cap("Tagged");
708	
709	    if let Some(unqueriable) = unqueriable
710	        && locatable.is_none()
711	    {
712	        bail!(unqueriable, "only `Locatable` element can be marked `Unqueriable`");
713	    }
714	
715	    let locatable = locatable.is_some();
716	    let unqueriable = unqueriable.is_some();
717	    let tagged = tagged.is_some();
718	    Ok(quote! {
719	        #foundations::IntrospectionCapabilities {
720	            locatable: #locatable,
721	            unqueriable: #unqueriable,
722	            tagged: #tagged,
723	        }
724	    })
725	}
726	
727	/// Creates the element's `Mathy` implementation.
728	fn create_mathy_impl(element: &Elem) -> TokenStream {
729	    let ident = &element.ident;
730	    quote! { impl ::typst_library::math::Mathy for #foundations::Packed<#ident> {} }
731	}
