1	use heck::ToKebabCase;
2	use proc_macro2::TokenStream;
3	use quote::quote;
4	use syn::parse::{Parse, ParseStream};
5	use syn::punctuated::Punctuated;
6	use syn::{DeriveInput, Ident, Result, Token};
7	
8	use crate::util::{documentation, foundations};
9	
10	/// Expand the `#[derive(Cast)]` macro.
11	pub fn derive_cast(item: DeriveInput) -> Result<TokenStream> {
12	    let ty = &item.ident;
13	
14	    let syn::Data::Enum(data) = &item.data else {
15	        bail!(item, "only enums are supported");
16	    };
17	
18	    let mut variants = vec![];
19	    for variant in &data.variants {
20	        if let Some((_, expr)) = &variant.discriminant {
21	            bail!(expr, "explicit discriminant is not allowed");
22	        }
23	
24	        let string = if let Some(attr) =
25	            variant.attrs.iter().find(|attr| attr.path().is_ident("string"))
26	        {
27	            attr.parse_args::<syn::LitStr>()?.value()
28	        } else {
29	            variant.ident.to_string().to_kebab_case()
30	        };
31	
32	        variants.push(Variant {
33	            ident: variant.ident.clone(),
34	            string,
35	            docs: documentation(&variant.attrs)?,
36	        });
37	    }
38	
39	    let strs_to_variants = variants.iter().map(|Variant { ident, string, docs }| {
40	        quote! {
41	            #[doc = #docs]
42	            #string => Self::#ident
43	        }
44	    });
45	
46	    let variants_to_strs = variants.iter().map(|Variant { ident, string, .. }| {
47	        quote! {
48	            #ty::#ident => #string
49	        }
50	    });
51	
52	    Ok(quote! {
53	        #foundations::cast! {
54	            #ty,
55	            self => #foundations::IntoValue::into_value(match self {
56	                #(#variants_to_strs),*
57	            }),
58	            #(#strs_to_variants),*
59	        }
