384	/// Creates the element's `NativeElement` implementation.
385	fn create_native_elem_impl(element: &Elem) -> Result<TokenStream> {
386	    let Elem {
387	        name, ident, title, since, scope, keywords, docs, ..
388	    } = element;
389	    let def_site_key = ident.to_string();
390	
391	    let since = quote_option(since);
392	
393	    let fields = element.fields.iter().filter(|field| !field.internal).map(|field| {
394	        let i = field.i;
395	        if field.external {
396	            let positional = field.positional;
397	            let required = field.required;
398	            quote! { #foundations::ExternalFieldData::<#ident, #i>::vtable(#positional, #required) }
399	        } else if field.variadic {
400	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable_variadic() }
401	        } else if field.required {
402	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable() }
403	        } else if field.synthesized {
404	            quote! { #foundations::SynthesizedFieldData::<#ident, #i>::vtable() }
405	        } else if field.ghost {
406	            quote! { #foundations::SettablePropertyData::<#ident, #i>::vtable() }
407	        } else {
408	            quote! { #foundations::SettableFieldData::<#ident, #i>::vtable() }
409	        }
410	    });
411	
412	    let field_arms = element
413	        .fields
414	        .iter()
415	        .filter(|field| !field.internal && !field.external)
416	        .map(|field| {
417	            let Field { name, i, .. } = field;
418	            quote! { #name => Some(#i) }
419	        });
420	    let field_id = quote! {
421	        |name| match name {
422	            #(#field_arms,)*
423	            _ => None,
424	        }
425	    };
426	
427	    let capable_func = create_capable_func(element);
428	    let introspection = create_introspection_capabilities(element)?;
429	
430	    let with_keywords =
431	        (!keywords.is_empty()).then(|| quote! { .with_keywords(&[#(#keywords),*]) });
432	    let with_repr = element.can("Repr").then(|| quote! { .with_repr() });
433	    let with_partial_eq = element.can("PartialEq").then(|| quote! { .with_partial_eq() });
434	    let with_local_name = element.can("LocalName").then(|| quote! { .with_local_name() });
435	    let with_scope = scope.then(|| quote! { .with_scope() });
436	
437	    Ok(quote! {
438	        unsafe impl #foundations::NativeElement for #ident {
439	            const ELEM: #foundations::Element = #foundations::Element::from_vtable({
440	                static STORE: #foundations::LazyElementStore
441	                    = #foundations::LazyElementStore::new();
442	                static VTABLE: #foundations::ContentVtable =
443	                    #foundations::ContentVtable::new::<#ident>(
444	                        #name,
445	                        #title,
446	                        #since,
447	                        #docs,
448	                        ::typst_utils::DefSite { path: file!(), key: #def_site_key },
449	                        &[#(#fields),*],
450	                        #field_id,
451	                        #capable_func,
452	                        #introspection,
453	                        || &STORE,
454	                    ) #with_keywords
455	                    #with_repr
456	                    #with_partial_eq
457	                    #with_local_name
458	                    #with_scope
459	                    .erase();
460	                &VTABLE
461	            });
462	        }
463	    })
464	}
