466	/// Creates the appropriate trait implementation for a field.
467	fn create_field_impl(element: &Elem, field: &Field) -> TokenStream {
468	    let elem_ident = &element.ident;
469	    let Field { i, ty, ident, default, positional, name, docs, .. } = field;
470	    let def_site_key = format!("{elem_ident}::{ident}");
471	    let def_site = quote! {
472	        ::typst_utils::DefSite { path: file!(), key: #def_site_key }
473	    };
474	
475	    let default = match default {
476	        Some(default) => quote! { || #default },
477	        None => quote! { std::default::Default::default },
478	    };
479	
480	    if field.external {
481	        quote! {
482	            impl #foundations::ExternalField<#i> for #elem_ident {
483	                type Type = #ty;
484	                const FIELD: #foundations::ExternalFieldData<Self, #i> =
485	                    #foundations::ExternalFieldData::<Self, #i>::new(
486	                        #name,
487	                        #docs,
488	                        #def_site,
489	                        #default,
490	                    );
491	            }
492	        }
493	    } else if field.required {
494	        quote! {
495	            impl #foundations::RequiredField<#i> for #elem_ident {
496	                type Type = #ty;
497	                const FIELD: #foundations::RequiredFieldData<Self, #i> =
498	                    #foundations::RequiredFieldData::<Self, #i>::new(
499	                        #name,
500	                        #docs,
501	                        #def_site,
502	                        |elem| &elem.#ident,
503	                    );
504	            }
505	        }
506	    } else if field.synthesized {
507	        quote! {
508	            impl #foundations::SynthesizedField<#i> for #elem_ident {
509	                type Type = #ty;
510	                const FIELD: #foundations::SynthesizedFieldData<Self, #i> =
511	                    #foundations::SynthesizedFieldData::<Self, #i>::new(
512	                        #name,
513	                        #docs,
514	                        #def_site,
515	                        |elem| &elem.#ident,
516	                    );
517	            }
518	        }
519	    } else {
520	        let slot = quote! {
521	            || {
522	                static LOCK: ::std::sync::OnceLock<#ty> = ::std::sync::OnceLock::new();
523	                &LOCK
524	            }
525	        };
526	
527	        let with_fold = field.fold.then(|| quote! { .with_fold() });
528	        let refable = (!field.fold).then(|| {
529	            quote! {
530	                impl #foundations::RefableProperty<#i> for #elem_ident {}
531	            }
532	        });
533	
534	        if field.ghost {
535	            quote! {
536	                impl #foundations::SettableProperty<#i> for #elem_ident {
537	                    type Type = #ty;
538	                    const FIELD: #foundations::SettablePropertyData<Self, #i> =
539	                        #foundations::SettablePropertyData::<Self, #i>::new(
540	                            #name,
541	                            #docs,
542	                            #def_site,
543	                            #positional,
544	                            #default,
545	                            #slot,
546	                        ) #with_fold;
547	                }
548	                #refable
549	            }
550	        } else {
551	            quote! {
552	                impl #foundations::SettableField<#i> for #elem_ident {
553	                    type Type = #ty;
554	                    const FIELD: #foundations::SettableFieldData<Self, #i> =
555	                        #foundations::SettableFieldData::<Self, #i>::new(
556	                            #name,
557	                            #docs,
558	                            #def_site,
559	                            #positional,
560	                            |elem| &elem.#ident,
561	                            |elem| &mut elem.#ident,
562	                            #default,
563	                            #slot,
564	                        ) #with_fold;
565	                }
566	                #refable
567	            }
568	        }
569	    }
570	}
