572	/// Creates the element's `Construct` implementation.
573	fn create_construct_impl(element: &Elem) -> TokenStream {
574	    let ident = &element.ident;
575	    let setup = element.construct_fields().map(|field| {
576	        let (prefix, value) = create_field_parser(field);
577	        let ident = &field.ident;
578	        quote! {
579	            #prefix
580	            let #ident = #value;
581	        }
582	    });
583	
584	    let fields = element.struct_fields().map(|field| {
585	        let ident = &field.ident;
586	        if field.required {
587	            quote! { #ident }
588	        } else if field.synthesized {
589	            quote! { #ident: None }
590	        } else {
591	            quote! { #ident: #foundations::Settable::from(#ident) }
592	        }
593	    });
594	
595	    quote! {
596	        impl #foundations::Construct for #ident {
597	            fn construct(
598	                engine: &mut ::typst_library::engine::Engine,
599	                args: &mut #foundations::Args,
600	            ) -> ::typst_library::diag::SourceResult<#foundations::Content> {
601	                #(#setup)*
602	                Ok(#foundations::Content::new(Self { #(#fields),* }))
603	            }
604	        }
605	    }
606	}
