636	/// Create argument parsing code for a field.
637	fn create_field_parser(field: &Field) -> (TokenStream, TokenStream) {
638	    if let Some(BlockWithReturn { prefix, expr }) = &field.parse {
639	        return (quote! { #(#prefix);* }, quote! { #expr });
640	    }
641	
642	    let name = &field.name;
643	    let value = if field.variadic {
644	        quote! { args.all()? }
645	    } else if field.required {
646	        quote! { args.expect(#name)? }
647	    } else if field.positional {
648	        quote! { args.find()? }
649	    } else {
650	        quote! { args.named(#name)? }
651	    };
652	
653	    (quote! {}, value)
654	}
