656	/// Creates the element's casting vtable.
657	fn create_capable_func(element: &Elem) -> TokenStream {
658	    // Forbidden capabilities, i.e capabilities that are not object safe or
659	    // introspection capabilities that are handled otherwise.
660	    const FORBIDDEN: &[&str] = &[
661	        // Not object safe.
662	        "Debug",
663	        "PartialEq",
664	        "Hash",
665	        "Construct",
666	        "Set",
667	        "Repr",
668	        "LocalName",
669	        // Introspection capabilities.
670	        "Locatable",
671	        "Unqueriable",
672	        "Tagged",
673	    ];
674	
675	    let ident = &element.ident;
676	    let relevant = element
677	        .capabilities
678	        .iter()
679	        .filter(|&ident| !FORBIDDEN.contains(&(&ident.to_string() as &str)));
680	
681	    let checks = relevant.map(|capability| {
682	        quote! {
683	            if capability == ::std::any::TypeId::of::<dyn #capability>() {
684	                // Safety: The vtable function doesn't require initialized
685	                // data, so it's fine to use a dangling pointer.
686	                return Some(unsafe {
687	                    ::typst_utils::fat::vtable(dangling as *const dyn #capability)
688	                });
689	            }
690	        }
691	    });
692	
693	    quote! {
694	        |capability| {
695	            let dangling = ::std::ptr::NonNull::<#foundations::Packed<#ident>>::dangling().as_ptr();
696	            #(#checks)*
697	            None
698	        }
699	    }
700	}
701	
702	/// Creates the element's casting vtable.
703	fn create_introspection_capabilities(element: &Elem) -> Result<TokenStream> {
704	    let find_cap = |name| element.capabilities.iter().find(|ident| *ident == name);
705	    let locatable = find_cap("Locatable");
706	    let unqueriable = find_cap("Unqueriable");
707	    let tagged = find_cap("Tagged");
708	
709	    if let Some(unqueriable) = unqueriable
710	        && locatable.is_none()
711	    {
712	        bail!(unqueriable, "only `Locatable` element can be marked `Unqueriable`");
713	    }
714	
715	    let locatable = locatable.is_some();
716	    let unqueriable = unqueriable.is_some();
717	    let tagged = tagged.is_some();
718	    Ok(quote! {
719	        #foundations::IntrospectionCapabilities {
720	            locatable: #locatable,
721	            unqueriable: #unqueriable,
722	            tagged: #tagged,
723	        }
724	    })
725	}
