63	/// An enum variant in a `derive(Cast)`.
64	struct Variant {
65	    ident: Ident,
66	    string: String,
67	    docs: String,
68	}
69	
70	/// Expand the `cast!` macro.
71	pub fn cast(stream: TokenStream) -> Result<TokenStream> {
72	    let input: CastInput = syn::parse2(stream)?;
73	    let ty = &input.ty;
74	    let castable_body = create_castable_body(&input);
75	    let input_body = create_input_body(&input)?;
76	    let output_body = create_output_body(&input);
77	    let into_value_body = create_into_value_body(&input);
78	    let from_value_body = create_from_value_body(&input);
79	
80	    let reflect = (!input.from_value.is_empty() || input.dynamic).then(|| {
81	        quote! {
82	            impl #foundations::Reflect for #ty {
83	                fn input() -> #foundations::CastInfo {
84	                    #input_body
85	                }
86	
87	                fn output() -> #foundations::CastInfo {
88	                    #output_body
89	                }
