98	    let into_value = (input.into_value.is_some() || input.dynamic).then(|| {
99	        quote! {
100	            impl #foundations::IntoValue for #ty {
101	                fn into_value(self) -> #foundations::Value {
102	                    #into_value_body
103	                }
104	            }
