133	impl Parse for CastInput {
134	    fn parse(input: ParseStream) -> Result<Self> {
135	        let mut dynamic = false;
136	        if input.peek(syn::Token![type]) {
137	            let _: syn::Token![type] = input.parse()?;
138	            dynamic = true;
139	        }
140	
141	        let ty = input.parse()?;
142	        let _: syn::Token![,] = input.parse()?;
143	
144	        let mut to_value = None;
145	        if input.peek(syn::Token![self]) {
146	            let _: syn::Token![self] = input.parse()?;
147	            let _: syn::Token![=>] = input.parse()?;
148	            to_value = Some(input.parse()?);
149	            let _: syn::Token![,] = input.parse()?;
150	        }
151	
152	        let from_value = Punctuated::parse_terminated(input)?;
153	        Ok(Self { ty, dynamic, into_value: to_value, from_value })
154	    }
