158	    fn parse(input: ParseStream) -> Result<Self> {
159	        let attrs = input.call(syn::Attribute::parse_outer)?;
160	        let pattern = input.parse()?;
161	        let _: syn::Token![=>] = input.parse()?;
162	        let expr = input.parse()?;
