167	impl Parse for Pattern {
168	    fn parse(input: ParseStream) -> Result<Self> {
169	        if input.peek(syn::LitStr) {
170	            Ok(Pattern::Str(input.parse()?))
171	        } else {
172	            let pat = syn::Pat::parse_single(input)?;
173	            let _: syn::Token![:] = input.parse()?;
174	            let ty = input.parse()?;
