194	fn create_castable_body(input: &CastInput) -> TokenStream {
195	    let mut strings = vec![];
196	    let mut casts = vec![];
197	
198	    for cast in &input.from_value {
199	        match &cast.pattern {
200	            Pattern::Str(lit) => {
201	                strings.push(quote! { #lit => return true });
202	            }
203	            Pattern::Ty(_, ty) => {
204	                casts.push(quote! {
205	                    if <#ty as #foundations::Reflect>::castable(value) {
206	                        return true;
207	                    }
208	                });
209	            }
210	        }
211	    }
212	
213	    let dynamic_check = input.dynamic.then(|| {
214	        quote! {
215	            if let #foundations::Value::Dyn(dynamic) = &value {
216	                if dynamic.is::<Self>() {
217	                    return true;
218	                }
219	            }
220	        }
221	    });
222	
223	    let str_check = (!strings.is_empty()).then(|| {
224	        quote! {
225	            if let #foundations::Value::Str(string) = &value {
226	                match string.as_str() {
227	                    #(#strings,)*
228	                    _ => {}
229	                }
230	            }
231	        }
232	    });
233	
234	    quote! {
235	        #dynamic_check
236	        #str_check
237	        #(#casts)*
238	        false
239	    }
240	}
241	
242	fn create_input_body(input: &CastInput) -> Result<TokenStream> {
243	    let mut infos = vec![];
244	
245	    for cast in &input.from_value {
246	        let docs = documentation(&cast.attrs)?;
247	        infos.push(match &cast.pattern {
248	            Pattern::Str(lit) => {
249	                quote! {
250	                    #foundations::CastInfo::Value(
251	                        #foundations::IntoValue::into_value(#lit),
252	                        #docs,
253	                    )
254	                }
255	            }
256	            Pattern::Ty(_, ty) => {
257	                quote! { <#ty as #foundations::Reflect>::input() }
258	            }
259	        });
260	    }
261	
262	    if input.dynamic {
263	        infos.push(quote! {
264	            #foundations::CastInfo::Type(#foundations::Type::of::<Self>())
265	        });
266	    }
267	
268	    Ok(quote! {
269	        #(#infos)+*
270	    })
271	}
272	
273	fn create_output_body(input: &CastInput) -> TokenStream {
274	    if input.dynamic {
275	        quote! { #foundations::CastInfo::Type(#foundations::Type::of::<Self>()) }
276	    } else {
277	        quote! { <Self as #foundations::Reflect>::input() }
278	    }
279	}
280	
281	fn create_into_value_body(input: &CastInput) -> TokenStream {
282	    if let Some(expr) = &input.into_value {
283	        quote! { #expr }
284	    } else {
285	        quote! { #foundations::Value::dynamic(self) }
286	    }
287	}
288	
289	fn create_from_value_body(input: &CastInput) -> TokenStream {
290	    let mut string_arms = vec![];
291	    let mut cast_checks = vec![];
292	
293	    for cast in &input.from_value {
294	        let expr = &cast.expr;
295	        match &cast.pattern {
296	            Pattern::Str(lit) => {
297	                string_arms.push(quote! { #lit => return Ok(#expr) });
298	            }
299	            Pattern::Ty(binding, ty) => {
300	                cast_checks.push(quote! {
301	                    if <#ty as #foundations::Reflect>::castable(&value) {
302	                        let #binding = <#ty as #foundations::FromValue>::from_value(value)?;
303	                        return Ok(#expr);
304	                    }
305	                });
306	            }
307	        }
308	    }
309	
310	    let dynamic_check = input.dynamic.then(|| {
311	        quote! {
312	            if let #foundations::Value::Dyn(dynamic) = &value {
313	                if let Some(concrete) = dynamic.downcast::<Self>() {
314	                    return Ok(concrete.clone());
315	                }
316	            }
317	        }
318	    });
319	
320	    let str_check = (!string_arms.is_empty()).then(|| {
321	        quote! {
322	            if let #foundations::Value::Str(string) = &value {
323	                match string.as_str() {
324	                    #(#string_arms,)*
325	                    _ => {}
326	                }
327	            }
328	        }
329	    });
330	
331	    quote! {
332	        #dynamic_check
333	        #str_check
334	        #(#cast_checks)*
335	        Err(<Self as #foundations::Reflect>::error(&value))
336	    }
337	}
