}

/// A pointer to a native function's implementation.
pub struct NativeFuncPtr(pub &'static NativeFuncSignature);

/// The signature of a native function's implementation.
type NativeFuncSignature =
    dyn Fn(&mut Engine, Tracked<Context>, &mut Args) -> SourceResult<Value> + Send + Sync;

impl Debug for NativeFuncPtr {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.pad("NativeFuncPtr(..)")
    }
}

/// A `LazyLock` that uses a static closure for initialization instead of only
/// working with function pointers.
///
/// Can be created from a normal function or closure by prepending with a `&`,
/// e.g. `LazyLock::new(&|| "hello")`. Can be created from a dynamic closure
/// by allocating and then leaking it. This is equivalent to having it
/// statically allocated, but allows for it to be generated at runtime.
type DynLazyLock<T> = LazyLock<T, &'static (dyn Fn() -> T + Send + Sync)>;

/// Describes a function parameter.
#[derive(Debug, Clone)]
pub struct NativeParamInfo {
    /// The parameter's name.
    pub name: &'static str,
    /// Documentation for the parameter.
    pub docs: &'static str,
    /// Where the parameter is defined in the source code.
    pub def_site: Option<DefSite>,
    /// Describe what values this parameter accepts.
    pub input: CastInfo,
    /// Creates an instance of the parameter's default value.
    pub default: Option<fn() -> Value>,
    /// Is the parameter positional?
    pub positional: bool,
    /// Is the parameter named?
    ///
    /// Can be true even if `positional` is true if the parameter can be given
    /// in both variants.
    pub named: bool,
    /// Can the parameter be given any number of times?
    pub variadic: bool,
    /// Is the parameter required?
    pub required: bool,
    /// Is the parameter settable with a set rule?
    pub settable: bool,
}

/// Distinguishes between variants of closures.
#[derive(Debug, Hash)]
pub enum ClosureNode {
    /// A regular closure. Must always be castable to a `ast::Closure`.
    Closure(SyntaxNode),
    /// Synthetic closure used for `context` expressions. Can be any `ast::Expr`
    /// and has no parameters.

/// }))
/// ```
#[constant(title = "Predefined color maps", since = "0.9.0")]
pub const MAP: fn() -> Module = || typst_utils::singleton!(Module, map()).clone();

/// Creates a grayscale color.
///
/// A grayscale color is represented by a lightness and an alpha component.
///
/// The value of these components can be obtained for an existing luma color
/// using the @color.components[`components`] method.
///
/// ```example
/// #for x in range(256, step: 50) {
///   box(square(fill: luma(x)))
/// }
/// ```
#[func(since = "forever")]
pub fn luma(
    args: &mut Args,
    /// The lightness component.
    #[external]
    lightness: Component,
    /// The alpha component.
    #[external]
    #[default(Component::ONE)]
    alpha: Component,
    /// Alternatively: The color to convert to grayscale.
    ///
    /// If this is given, the individual components should not be given.
    ///
    /// ```example
    /// #let colors = (red, green, blue)
    ///
    /// #for c in colors {
    ///   box(square(fill: c))
    /// }
    ///
    /// #for c in colors {
    ///   box(square(fill: luma(c)))
    /// }
    /// ```
    #[external]
    color: Color,
) -> SourceResult<Color> {
    Ok(Self::Process(ProcessColor::Luma(
        if let Some(color) = args.find::<Color>()? {
            color.to_luma()
        } else {
            let missing_lightness = args.is_empty();
            let Component(l) =
                args.expect("lightness component").map_err(|mut err| {
                    if missing_lightness {
                        // Before 0.16, lightness accidentally defaulted to
                        // `100%`, so this should help with breakage. I
                        // could not find a cleaner way to add the hint >:(
                        let last = err.make_mut().last_mut().unwrap();
                        last.hint("try writing `white` or `luma(100%)`");
                    }
                    err
                })?;
            let Component(alpha) = args.eat()?.unwrap_or(Component(Ratio::one()));
            Luma::new(l.get() as f32, alpha.get() as f32)
        },
    )))
}

