//! Exposes metadata about the standard library to the docs system.
//!
//! Cooperates with `docs/components/reflect.typ`.

use std::cmp::Ordering;
use std::path::Path;
use std::sync::LazyLock;

use ecow::EcoString;
use heck::ToTitleCase;
use icu_collator::options::{CollatorOptions, Strength};
use icu_collator::preferences::CollationType;
use icu_collator::{Collator, CollatorPreferences};
use rustc_hash::FxHashMap;
use typst::diag::bail;
use typst::foundations::{
    Array, CastInfo, Dict, Func, IntoValue, Module, NativeParamInfo, Repr, Str, Symbol,
    Type, Value, cast, dict, func,
};
use typst::syntax::{RootedPath, VirtualPath, VirtualRoot};
use typst::text::RawElem;
use typst_utils::DefSite;
use unicode_math_class::MathClass;
use unicode_segmentation::UnicodeSegmentation;
use unscanny::Scanner;

use crate::world::REPO_ROOT;

/// A value that can have a scope.
pub enum ToScope {
    Module(Module),
    Type(Type),
    Func(Func),
}

cast! {
    ToScope,
    m: Module => Self::Module(m),
    t: Type => Self::Type(t),
    f: Func => Self::Func(f),
}

/// Provides details about a binding in a module.
#[func]
pub fn binding(scope: ToScope, name: EcoString) -> Option<Dict> {
    let scope = match &scope {
        ToScope::Module(module) => module.scope(),
        ToScope::Type(ty) => ty.scope(),
        ToScope::Func(func) => func.scope()?,
    };
    let binding = scope.get(&name)?;
    Some(dict! {
        "category" => binding.category().map(|c| c.name()),
        "feature" => binding.feature().map(|f| f.to_string()),
        "deprecation" => binding.deprecation().map(|d| dict! {
            "message" => d.message(),
            "until" => d.until(),
        }),
        "name" => binding.name(),
        "title" => binding.title(),
        "docs" => binding.docs(),
        "since" => binding.since(),
        "keywords" => binding.keywords(),
        "def-site" => binding.def_site().map(describe_def_site),
    })
}

/// Provides details about a value.
#[func]
pub fn describe(value: Value) -> Option<Dict> {
    match &value {
        Value::Func(func) => Some(describe_func(func)),
        Value::Type(ty) => Some(describe_ty(*ty)),
        Value::Symbol(symbol) => Some(describe_symbol(symbol)),
        _ => None,
    }
}

/// Provides details about a native function.
fn describe_func(func: &Func) -> Dict {
    dict! {
        "name" => func.name(),
        "title" => func.title(),
        "since" => func.since(),
        "docs" => func.docs(),
        "def-site" => func.def_site().map(describe_def_site),
        "element" => func.to_element().is_some(),
        "locatable" => func.to_element().is_some_and(|elem| elem.is_locatable()),
        "contextual" => func.contextual(),
        "params" => func
            .params()
            .filter_map(|info| {
                info.to_native().map(|info| describe_param(info).into_value())
            })
            .collect::<Array>(),
        "returns" => func.returns().map(describe_cast_info),
        "keywords" => func.keywords(),
        "scope" => func.scope().map(|s| Module::anonymous(s.clone())),
    }
}

/// Provides details about a parameter of a native function.
fn describe_param(param: &NativeParamInfo) -> Dict {
    let mut dict = dict! {
        "name" => param.name,
        "docs" => param.docs,
        "def-site" => param.def_site.map(describe_def_site),
        "input" => describe_cast_info(&param.input),
        "positional" => param.positional,
        "named" => param.named,
        "variadic" => param.variadic,
        "required" => param.required,
        "settable" => param.settable,
    };
    // Since the default can be _any_ Typst value (including `none`), we
    // indicate the absence of a default with absence from the dictionary rather
    // than `none`.
    if let Some(f) = param.default {
        dict.insert("default".into(), f());
    }
    dict
}

/// Provides details about a native type.
fn describe_ty(ty: Type) -> Dict {
    dict! {
        "short-name" => ty.short_name(),
        "long-name" => ty.long_name(),
        "title" => ty.title(),
        "since" => ty.since(),

